#include <array>
using Callback = int (*)();
static int alpha() { return 11; }
static int beta() { return 22; }
static const std::array<Callback, 2>& providers() {
    static const auto cache = [] {
        std::array<Callback, 2> entries{};
        entries.fill(&alpha);
        entries[0] = &beta;
        return entries;
    }();
    return cache;
}
static unsigned select_slot(unsigned raw) { return static_cast<unsigned>(raw & 0U); }
int main() { return providers()[select_slot(0)](); }

